"""Contrato da folha operacional somente de leitura; sem SDK ou inicialização de estado."""

from __future__ import annotations

from dataclasses import dataclass
from enum import StrEnum
from typing import Literal

type EntradaJSON = None | bool | int | float | str | list["EntradaJSON"] | dict[str, "EntradaJSON"]
type JSONFechado = dict[str, EntradaJSON]
type SchemaJSONFechado = JSONFechado


class FerramentaLeitura(StrEnum):
    ESTADO = "consultar_estado"
    AGENDA = "consultar_agenda"
    INTEGRIDADE = "verificar_integridade"
    FATOS = "ler_fatos"
    VALIDAR = "validar_documento"
    CARTEIRA = "ler_carteira"
    RISCO = "decompor_risco_operacional"
    COBERTURA = "ler_modelo_cobertura"
    PACOTE = "ler_pacote_mente"


CODIGOS_FALHA = (
    "CONTEXTO_DESCONHECIDO",
    "INGRESSO_INVALIDO",
    "SELETOR_INCOMPATIVEL",
    "ARQUIVO_AUSENTE",
    "PREPARADO_AUSENTE",
    "CORPO_INVALIDO",
    "INTEGRIDADE_DA_FONTE",
    "CORTE_NAO_COMPROVADO",
    "LEITURA_INSTAVEL",
    "LIMITE_DE_LEITURA",
    "RETORNO_NATIVO_NAO_SUPORTADO",
    "EFEITO_RECUSADO",
    "ERRO_NATIVO",
)


class ContextoLeituraInvalido(ValueError):
    """Manifesto declarado inválido; nenhum servidor deve ser iniciado."""


class IngressoLeituraInvalido(ValueError):
    """Ingresso fora do contrato, antes de abrir fontes da consulta."""


class FonteLeituraIndisponivel(Exception):
    def __init__(self, codigo: str, mensagem: str, membros: tuple[str, ...] = ()) -> None:
        super().__init__(mensagem)
        self.codigo = codigo
        self.mensagem = mensagem
        self.membros = membros


class TentativaDeEfeitoLeitura(BaseException):
    """Recusa própria não absorvível pelos except Exception dos produtores nativos."""


@dataclass(frozen=True, slots=True)
class FalhaLeitura:
    codigo: str
    mensagem: str
    membros: tuple[str, ...] = ()
    tipo_excecao_nativa: str | None = None


@dataclass(frozen=True, slots=True)
class ReferenciaFonte:
    membro_id: str
    raiz_id: str
    path_relativo: str
    sha256: str
    bytes: int
    dev: str
    ino: str
    mtime_ns: str
    ctime_ns: str
    mode: int
    nlink: int
    recebido_em: str


@dataclass(frozen=True, slots=True)
class RespostaConsulta:
    ferramenta: str
    contexto_sha256: str
    as_of: str
    conhecimento_ate: str
    agora: str
    recebido_em: str
    readset: tuple[ReferenciaFonte, ...]
    integridade: Literal["integro", "falho", "nao_verificado", "nao_aplicavel"]
    disponibilidade: Literal["recepcao_atual", "temporal_comprovada_no_recorte", "nao_comprovada"]
    semantica: Literal["validada_pelo_delegate", "negativa_pelo_delegate", "nao_avaliada"]
    hashes_nativos: tuple[tuple[str, str], ...]
    status: Literal["disponivel", "indisponivel", "recusado"]
    resultado: JSONFechado | None
    falha: FalhaLeitura | None
    resultado_sha256: str | None
    schema: str = "cdp.mcp.operacional/v1"
    capacidade: str = "leitura"
    autoridade_operacional: bool = False


