def schema_ingresso(ferramenta: str) -> SchemaJSONFechado:
    import json

    if type(ferramenta) is not str or ferramenta not in {x.value for x in FerramentaLeitura}:
        raise IngressoLeituraInvalido("Ferramenta desconhecida")
    return json.loads(_INGRESSOS_JSON)["ferramentas"][ferramenta]


def schema_valor_nativo() -> SchemaJSONFechado:
    import json

    return json.loads(_VALOR_NATIVO_JSON)


def schema_saida() -> SchemaJSONFechado:
    """Schema nominal fechado do envelope, compartilhado com o transporte."""
    valor = schema_valor_nativo()
    texto = {"type": "string"}
    sha = {"type": "string", "pattern": "^[0-9a-f]{64}$"}
    inteiro = {"type": "integer", "minimum": 0, "maximum": 9007199254740991}

    def objeto(properties):
        return {
            "type": "object",
            "properties": properties,
            "required": list(properties),
            "additionalProperties": False,
        }

    referencia = objeto(
        {
            "membro_id": texto,
            "raiz_id": texto,
            "path_relativo": texto,
            "sha256": sha,
            "bytes": inteiro,
            "dev": texto,
            "ino": texto,
            "mtime_ns": texto,
            "ctime_ns": texto,
            "mode": inteiro,
            "nlink": inteiro,
            "recebido_em": texto,
        }
    )
    falha = objeto(
        {
            "codigo": {"enum": list(CODIGOS_FALHA)},
            "mensagem": texto,
            "membros": {"type": "array", "items": texto},
            "tipo_excecao_nativa": {"type": ["string", "null"]},
        }
    )
    properties = {
        "schema": {"const": "cdp.mcp.operacional/v1"},
        "ferramenta": {"enum": [x.value for x in FerramentaLeitura]},
        "contexto_sha256": sha,
        "as_of": texto,
        "conhecimento_ate": texto,
        "agora": texto,
        "recebido_em": texto,
        "readset": {"type": "array", "items": referencia, "maxItems": 512},
        "integridade": {"enum": ["integro", "falho", "nao_verificado", "nao_aplicavel"]},
        "disponibilidade": {
            "enum": ["recepcao_atual", "temporal_comprovada_no_recorte", "nao_comprovada"]
        },
        "semantica": {"enum": ["validada_pelo_delegate", "negativa_pelo_delegate", "nao_avaliada"]},
        "hashes_nativos": {"type": "array", "items": objeto({"nome": texto, "sha256": sha})},
        "status": {"enum": ["disponivel", "indisponivel", "recusado"]},
        "resultado": {"oneOf": [{"$ref": "#/$defs/ValorNativo"}, {"type": "null"}]},
        "falha": {"oneOf": [falha, {"type": "null"}]},
        "resultado_sha256": {"oneOf": [sha, {"type": "null"}]},
        "capacidade": {"const": "leitura"},
        "autoridade_operacional": {"const": False},
    }
    return {"$schema": valor["$schema"], **objeto(properties), "$defs": valor["$defs"]}
